/* =============================================================================
   DIR-01 · Directorio de Organizaciones — pantalla
   =============================================================================
   Solo tokens de `:root` (design-system.md §1): ningún hex, ningún rgb().
   El fondo del panel de contenido lo pone el shell (`--bw-cold-white`), así que
   aquí no se repite.

   Nota de tokens: el mock usa `white` para la superficie de tarjeta, de campo y
   de botón. No existe un token de blanco puro en §1; se usa `--bw-warm-cream`
   (#FAF8F4), que es el más claro de la paleta y el más cercano al blanco del
   mock sin inventar un valor nuevo.
   ========================================================================== */

.page {
  display: flex;
  flex-direction: column;
}

/* ── Cabecera de la pantalla ─────────────────────────────────────────────── */

.eyebrow {
  margin: 0 0 4px;
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-eyebrow);
  color: var(--bw-steel-mist);
}

.title {
  margin: 0 0 6px;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-title);
  font-weight: 700;
  letter-spacing: var(--bw-ls-title);
  color: var(--bw-deep-steel);
}

.subtitle {
  margin: 0 0 18px;
  max-width: 560px;
  font-family: var(--bw-font-body);
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

/* ── Barra de filtros ────────────────────────────────────────────────────── */

.filterBar {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}

.select {
  height: 36px;
  padding: 0 10px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  background: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-ink-steel);
  cursor: pointer;
  transition: border-color 0.15s;
}

.select:focus {
  outline: none;
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.searchWrap {
  position: relative;
  flex: 1;
  max-width: 280px;
  min-width: 180px;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 36px 0 12px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  background: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
  transition: border-color 0.15s;
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.searchInput:focus {
  outline: none;
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

/* La lupa es un botón de verdad: la spec §3 pide que la búsqueda se dispare
   «al pulsar Enter o icono lupa», y un icono que no es un control no existe
   para el teclado. */
.searchButton {
  position: absolute;
  right: 4px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: none;
  border-radius: var(--bw-radius);
  background: none;
  color: var(--bw-steel-mist);
  cursor: pointer;
  transition: color 0.12s;
}

.searchButton:hover {
  color: var(--bw-calibration-blue);
}

.searchButton:focus-visible {
  outline: none;
  box-shadow: var(--bw-focus-halo);
}

.clearButton {
  padding: 4px 8px;
  border: none;
  background: none;
  font-family: var(--bw-font-body);
  font-size: 12px;
  font-weight: 500;
  color: var(--bw-steel-mist);
  white-space: nowrap;
  cursor: pointer;
  transition: color 0.12s;
}

.clearButton:hover {
  color: var(--bw-sensitive-text);
}

/* ── Zona de la tabla: carga y error ─────────────────────────────────────── */

.loading {
  padding: 28px 14px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  background: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-steel-mist);
  text-align: center;
}

.error {
  padding: 16px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 8px;
  background: var(--bw-tint-danger);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-error-text);
}

/* ── Paginación ──────────────────────────────────────────────────────────── */

.pagination {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  margin-top: 14px;
}

.pageInfo {
  margin-right: 6px;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  color: var(--bw-steel-mist);
}

.pageButton {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius-hamburger);
  background: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: 12px;
  color: var(--bw-ink-steel);
  cursor: pointer;
  transition:
    border-color 0.12s,
    color 0.12s;
}

.pageButton:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageButton:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

/* La página actual. El color no es la única señal: el botón lleva
   `aria-current="page"`. */
.currentPage {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
  cursor: default;
}

.currentPage:hover {
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
}

